use std::io

fn main() {
    let input = io::read_to_string() ?? ""
    for line in input.lines() {
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        println(eval(t))
    }
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = Vec::new()
    for tok in line.split(" ") {
        if tok == "+" || tok == "-" || tok == "*" || tok == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b = st.pop() ?? 0
            let a = st.pop() ?? 0
            if tok == "+" {
                st.push(a + b)
            } else if tok == "-" {
                st.push(a - b)
            } else if tok == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else {
            match tok.parse::<int>() {
                Ok(v) => st.push(v),
                Err(_) => return "error: token",
            }
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    st[0].to_string()
}

